INSERT INTO `package` (`id`, `name`, `type_id`, `price`, `contact_person`, `description`, `cover_url`, `video_url`, `min_capacity`, `custom`) VALUES
('P0001', 'Fishermans Friend', 'T0001', 60000, '082383985824', 'The uniqueness of GTP Ulakan is not only related to its natural tourism and water attractions, but also the management and utilization of its potential by Pokdarwis by providing various kinds of tour packages such as the Fisherman\'s Friends package so that tourists can get to know the daily activities of the Ulakan people as fishermen. Tourists will be invited to look for lokan, langkitang, palm fruit, palm leaves and mangrove crabs.', '1.jpg', '1700831199_15bb9f0e02c0c8891ec7.mp4', 10, 0),
('P0002', 'Weaving Pandan Mats', 'T0001', 150000, '082383985824', 'In the Mangayam Lapiak/Mat from Pandan package, tourists will be invited to learn about the stages in making lapiak/mats from pandan and be accompanied by a pandan craftsman. The results of making these lapiak/mats can be taken home by tourists.', '6.jpg', '1700831883_5e5e657e1b0559556c0a.mp4', 10, 0),
('P0004', 'Family and Community Gathering', 'T0005', 1500000, '082383985824', 'The Mangaca Talao Package is a tour package that offers the experience of participating in activities in Talao. Here, tourists can take part in various activities, including picking fresh palm fruit with their own hands, harvesting lokan, and catching mangrove crabs. Participants can not only enjoy various activities, but the results of these activities can be taken home as souvenirs from their adventure in Talao.', '1699936600_363c7c02d36a0128b338.jpg', 'template_video.mp4', 30, 0),
('P0005', 'Open Trip Pieh Island', 'T0003', 3000000, '082383985824', 'This package is for tourists who want to enjoy island tourism by taking a 1 day 1 night trip to Pieh Island', '11.jpg', '', 20, 0),
('P0006', 'Study Tour', 'T0004', 1500000, '082383985824', 'The Comparative Study Package is a formal package for institutions or communities who want to know how the Ulakan GTP was built and developed as well as other detailed information.', '15.JPG', 'template_video.mp4', 30, 0),
('P0007', 'Explore Talao', 'T0003', 1500000, '0812345678', 'This package invites tourists to explore the Green Talao Park village area and witness the activities of the surrounding community', '1704530807_3cd899ff613a8b5b2162.jpg', '1704530808_86fcb895a70bed06bd67.mp4', 15, 0),
('P0014', 'Cultural Exploration', 'T0002', 1370000, '0878629234', 'The Cultural and Arts Exploration tour package in Padang Pariaman, West Sumatra, is an adventure that introduces the rich charm of the area\'s cultural and artistic heritage. Tourists will be invited to explore the unique characteristics of the region, including traditional ceremonies, traditional dances, and various local works of art that reflect the lives of local people.', '1699387997_e201aa83ca3d1bd1e618.jpg', '1701263824_b00b11f8fe36b6c6f360.mp4', 10, 0),
('P0015', 'Mangaca Talao', 'T0002', 500000, '082111114786', 'The Mangaca Talao Package is a tour package that offers the experience of participating in activities in Talao. Here, tourists can take part in various activities, including picking fresh palm fruit with their own hands, harvesting lokan, and catching mangrove crabs. Participants can not only enjoy various activities, but the results of these activities can be taken home as souvenirs from their adventure in Talao.', '1749008059246_p3.jpg', '1749008059652_1697421485_9bc567814ec9fb74300b.mp4', 10, 0),
('P0016', 'Mangaca Talao extend by Lathif Nur Irsyad at 2025-06-20 10:27:46', 'T0002', 740000, '082383985824', 'The Mangaca Talao Package is a tour package that offers the experience of participating in activities in Talao. Here, tourists can take part in various activities, including picking fresh palm fruit with their own hands, harvesting lokan, and catching mangrove crabs. Participants can not only enjoy various activities, but the results of these activities can be taken home as souvenirs from their adventure in Talao.', NULL, NULL, 10, 1),
